import sys
from bisect import bisect_left

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    N = next(it); M = next(it); Q = next(it)
    a = [0] * (M + 1)
    b = [0] * (M + 1)
    sign = [0] * (M + 1)
    for i in range(1, M + 1):
        s = next(it); t = next(it)
        if s < t:
            a[i] = s; b[i] = t; sign[i] = 0
        else:
            a[i] = t; b[i] = s; sign[i] = 1

    queries = []
    for _ in range(Q):
        L = next(it); R = next(it)
        queries.append((L, R))

    bad_max = [0] * (M + 1)

    # Condition 1 & 2: same left or same right endpoint
    last_a = {}
    last_b = {}
    for i in range(1, M + 1):
        cand = 0
        if a[i] in last_a:
            cand = last_a[a[i]]
        if b[i] in last_b:
            if last_b[b[i]] > cand:
                cand = last_b[b[i]]
        if cand > bad_max[i]:
            bad_max[i] = cand
        last_a[a[i]] = i
        last_b[b[i]] = i

    # Precompute segment tree nodes covering each interval's interior (a_i, b_i)
    interval_nodes = [[] for _ in range(M + 1)]
    for i in range(1, M + 1):
        L = a[i]
        R = b[i] - 2
        if L <= R:
            l = L + N
            r = R + N
            nodes = []
            while l <= r:
                if l & 1:
                    nodes.append(l)
                    l += 1
                if not (r & 1):
                    nodes.append(r)
                    r -= 1
                l >>= 1
                r >>= 1
            interval_nodes[i] = nodes

    # Process same-sign crossing conditions
    for sgn in (0, 1):
        for cond in (3, 4):
            size = 2 * N
            node_keys = [None] * size

            # Collect keys for the segment tree
            for i in range(1, M + 1):
                if sign[i] != sgn:
                    continue
                nodes = interval_nodes[i]
                if not nodes:
                    continue
                if cond == 3:
                    key = b[i]
                else:
                    key = N + 1 - a[i]
                for node in nodes:
                    if node_keys[node] is None:
                        node_keys[node] = []
                    node_keys[node].append(key)

            # Build Fenwick trees inside each segment tree node
            node_bit = [None] * size
            for node in range(1, size):
                keys = node_keys[node]
                if keys:
                    keys = sorted(set(keys))
                    node_keys[node] = keys
                    node_bit[node] = [0] * (len(keys) + 1)

            # Process people in index order
            for r in range(1, M + 1):
                if sign[r] != sgn:
                    continue
                if cond == 3:
                    pos = a[r] - 1
                    thresh = b[r]
                else:
                    pos = b[r] - 1
                    thresh = N + 1 - a[r]

                # Point query at pos with key < thresh
                res = 0
                p = pos + N
                while p > 0:
                    keys = node_keys[p]
                    if keys:
                        bit = node_bit[p]
                        idx = bisect_left(keys, thresh)
                        i = idx
                        while i > 0:
                            if bit[i] > res:
                                res = bit[i]
                            i -= i & -i
                    p >>= 1

                if res > bad_max[r]:
                    bad_max[r] = res

                # Range update for person r
                nodes = interval_nodes[r]
                if nodes:
                    if cond == 3:
                        key = b[r]
                    else:
                        key = N + 1 - a[r]
                    val = r
                    for node in nodes:
                        keys = node_keys[node]
                        if keys:
                            bit = node_bit[node]
                            idx = bisect_left(keys, key) + 1
                            n = len(keys)
                            i = idx
                            while i <= n:
                                bit[i] = val
                                i += i & -i

    # Build segment tree for range maximum queries on bad_max
    seg_size = 1
    while seg_size < M:
        seg_size <<= 1
    seg = [0] * (2 * seg_size)
    for i in range(1, M + 1):
        seg[seg_size + i - 1] = bad_max[i]
    for i in range(seg_size - 1, 0, -1):
        seg[i] = max(seg[2 * i], seg[2 * i + 1])

    out = []
    for L, R in queries:
        l = L + seg_size - 1
        r = R + seg_size - 1
        mx = 0
        while l <= r:
            if l & 1:
                if seg[l] > mx:
                    mx = seg[l]
                l += 1
            if not (r & 1):
                if seg[r] > mx:
                    mx = seg[r]
                r -= 1
            l >>= 1
            r >>= 1
        if mx >= L:
            out.append("No")
        else:
            out.append("Yes")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # Any alternating sum has absolute value at most n * 12 <= 1800.
        if abs(k) > 1800:
            return -1

        OFFSET = 2000

        # DP for positive products only. Zeros are ignored here because
        # selecting a zero makes the product 0, which is handled separately.
        dp = [[0] * (limit + 1) for _ in range(2)]

        for x in nums:
            if x == 0:
                continue

            newdp = [dp[0][:], dp[1][:]]

            # Subsequence consisting only of x.
            if x <= limit:
                newdp[1][x] |= 1 << (OFFSET + x)

            for parity in (0, 1):
                src = dp[parity]
                dest = parity ^ 1

                if parity == 0:
                    # Next selected element is at an even index: add x.
                    for p in range(1, limit + 1):
                        bits = src[p]
                        if bits:
                            q = p * x
                            if q <= limit:
                                newdp[dest][q] |= bits << x
                else:
                    # Next selected element is at an odd index: subtract x.
                    for p in range(1, limit + 1):
                        bits = src[p]
                        if bits:
                            q = p * x
                            if q <= limit:
                                newdp[dest][q] |= bits >> x

            dp = newdp

        bitpos = OFFSET + k

        # Best positive product.
        for p in range(limit, 0, -1):
            if ((dp[0][p] >> bitpos) & 1) or ((dp[1][p] >> bitpos) & 1):
                return p

        # DP for product 0: subsequences containing at least one zero.
        # Flag 0/1 indicates whether a zero has been selected.
        dp2 = [[0, 0], [0, 0]]
        dp2[0][0] = 1 << OFFSET  # empty subsequence, sum 0

        for x in nums:
            newdp2 = [[dp2[0][0], dp2[0][1]], [dp2[1][0], dp2[1][1]]]

            for parity in (0, 1):
                for flag in (0, 1):
                    bits = dp2[parity][flag]
                    if not bits:
                        continue

                    nf = 1 if (flag or x == 0) else 0

                    if parity == 0:
                        shifted = bits << x
                    else:
                        shifted = bits >> x

                    newdp2[parity ^ 1][nf] |= shifted

            dp2 = newdp2

        if ((dp2[0][1] >> bitpos) & 1) or ((dp2[1][1] >> bitpos) & 1):
            return 0

        return -1

import sys

def solve() -> None:
    input = sys.stdin.readline
    T = int(input().strip())
    out_lines = []
    INF = 10**18

    for _ in range(T):
        N, K = map(int, input().split())
        items = []
        for _ in range(N):
            x, y, z = map(int, input().split())
            M = max(x, y, z)
            items.append((M, x, y, z))
        items.sort(key=lambda t: t[0], reverse=True)

        twoK = 2 * K
        T_items = items[:twoK]
        U_items = items[twoK:]
        B = sum(t[0] for t in T_items)

        count_T = [0, 0, 0]
        best1_cost = [[INF] * 4 for _ in range(3)]
        best1_idx = [[-1] * 4 for _ in range(3)]
        best2_cost = [[INF] * 4 for _ in range(3)]
        best2_idx = [[-1] * 4 for _ in range(3)]

        for idx, (M, x, y, z) in enumerate(T_items):
            vals = [x, y, z]
            if x == M:
                b = 0
            elif y == M:
                b = 1
            else:
                b = 2
            count_T[b] += 1

            # relabel targets 0,1,2
            for t in range(3):
                cost = M - vals[t]
                if cost < best1_cost[b][t]:
                    best2_cost[b][t] = best1_cost[b][t]
                    best2_idx[b][t] = best1_idx[b][t]
                    best1_cost[b][t] = cost
                    best1_idx[b][t] = idx
                elif idx != best1_idx[b][t] and cost < best2_cost[b][t]:
                    best2_cost[b][t] = cost
                    best2_idx[b][t] = idx

            # remove target 3
            cost = M
            if cost < best1_cost[b][3]:
                best2_cost[b][3] = best1_cost[b][3]
                best2_idx[b][3] = best1_idx[b][3]
                best1_cost[b][3] = cost
                best1_idx[b][3] = idx
            elif idx != best1_idx[b][3] and cost < best2_cost[b][3]:
                best2_cost[b][3] = cost
                best2_idx[b][3] = idx

        top1_un = [-1, -1, -1]
        top2_un = [-1, -1, -1]
        for M, x, y, z in U_items:
            vals = [x, y, z]
            for t in range(3):
                val = vals[t]
                if val > top1_un[t]:
                    top2_un[t] = top1_un[t]
                    top1_un[t] = val
                elif val > top2_un[t]:
                    top2_un[t] = val

        q = [c % 2 for c in count_T]
        if sum(q) == 0:
            out_lines.append(str(B))
            continue

        q_mask = (q[0] << 0) | (q[1] << 1) | (q[2] << 2)
        min_cost = INF

        edges = []
        for u in range(3):
            for v in range(3):
                if u != v:
                    edges.append((u, v))

        # size 1
        for e in edges:
            u, v = e
            if ((1 << u) ^ (1 << v)) != q_mask:
                continue
            # relabel
            cR = best1_cost[u][v]
            if cR < INF:
                if cR < min_cost:
                    min_cost = cR
            # swap
            cM = best1_cost[u][3]
            if cM < INF and len(U_items) > 0:
                cS = cM - top1_un[v]
                if cS < min_cost:
                    min_cost = cS

        # size 2
        L = len(edges)
        for i in range(L):
            for j in range(i + 1, L):
                e1 = edges[i]
                e2 = edges[j]
                mask = (1 << e1[0]) ^ (1 << e1[1]) ^ (1 << e2[0]) ^ (1 << e2[1])
                if mask != q_mask:
                    continue
                for t1 in (0, 1):          # 0: relabel, 1: swap
                    for t2 in (0, 1):
                        sel_tg = [[], [], []]
                        add_count = [0, 0, 0]
                        valid = True

                        for e, typ in ((e1, t1), (e2, t2)):
                            u, v = e
                            if typ == 0:       # relabel
                                sel_tg[u].append(v)
                            else:              # swap
                                sel_tg[u].append(3)
                                add_count[v] += 1

                        total = 0
                        for u in range(3):
                            tg = sel_tg[u]
                            if len(tg) == 0:
                                continue
                            elif len(tg) == 1:
                                t = tg[0]
                                c = best1_cost[u][t]
                                if c >= INF // 2:
                                    valid = False
                                    break
                                total += c
                            elif len(tg) == 2:
                                t1_, t2_ = tg[0], tg[1]
                                c1 = best1_cost[u][t1_]
                                i1 = best1_idx[u][t1_]
                                c2 = best1_cost[u][t2_]
                                i2 = best1_idx[u][t2_]
                                if c1 >= INF // 2 or c2 >= INF // 2:
                                    valid = False
                                    break
                                if i1 != i2:
                                    total += c1 + c2
                                else:
                                    s1 = best2_cost[u][t1_]
                                    s2 = best2_cost[u][t2_]
                                    opt = INF
                                    if s2 < INF // 2:
                                        opt = min(opt, c1 + s2)
                                    if s1 < INF // 2:
                                        opt = min(opt, s1 + c2)
                                    if opt >= INF // 2:
                                        valid = False
                                        break
                                    total += opt
                            else:
                                valid = False
                                break
                        if not valid:
                            continue

                        for v in range(3):
                            cnt = add_count[v]
                            if cnt == 0:
                                continue
                            elif cnt == 1:
                                if top1_un[v] == -1:
                                    valid = False
                                    break
                                total += -top1_un[v]
                            elif cnt == 2:
                                if top2_un[v] == -1:
                                    valid = False
                                    break
                                total += -(top1_un[v] + top2_un[v])
                            else:
                                valid = False
                                break
                        if not valid:
                            continue

                        if total < min_cost:
                            min_cost = total

        ans = B - min_cost
        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    S = input().strip()
    T = input().strip()

    mapping = [-1] * 26
    for i in range(N):
        c = ord(S[i]) - 97
        d = ord(T[i]) - 97
        if mapping[c] == -1:
            mapping[c] = d
        elif mapping[c] != d:
            print(-1)
            return

    # If both strings contain all 26 letters and are different, it's impossible.
    if len(set(S)) == 26 and len(set(T)) == 26 and S != T:
        print(-1)
        return

    next_node = [-1] * 26
    E = 0
    for c in range(26):
        if mapping[c] != -1 and mapping[c] != c:
            next_node[c] = mapping[c]
            E += 1

    indeg = [0] * 26
    for c in range(26):
        if next_node[c] != -1:
            indeg[next_node[c]] += 1

    indeg_temp = indeg.copy()
    q = deque()
    for i in range(26):
        if next_node[i] != -1 and indeg_temp[i] == 0:
            q.append(i)

    while q:
        u = q.popleft()
        v = next_node[u]
        if v != -1:
            indeg_temp[v] -= 1
            if indeg_temp[v] == 0:
                q.append(v)

    visited = [False] * 26
    isolated = 0
    for i in range(26):
        if next_node[i] != -1 and indeg_temp[i] > 0 and not visited[i]:
            cycle = []
            cur = i
            while not visited[cur]:
                visited[cur] = True
                cycle.append(cur)
                cur = next_node[cur]
            if all(indeg[node] == 1 for node in cycle):
                isolated += 1

    ans = E + isolated
    print(ans)

if __name__ == "__main__":
    solve()

import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    A = data[2:2 + N]

    # binomial coefficients C[K][t]
    C = [[0] * (K + 1) for _ in range(K + 1)]
    for n in range(K + 1):
        C[n][0] = C[n][n] = 1
        for r in range(1, n):
            C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD

    binom = C[K]
    sign = [1 if p % 2 == 0 else -1 for p in range(K + 1)]

    cnt = [0] * (K + 1)
    cnt[0] = 1  # S_0^0, and S_0^p = 0 for p > 0

    ans = 0
    s = 0

    for a in A:
        s = (s + a) % MOD

        pows = [1] * (K + 1)
        for t in range(1, K + 1):
            pows[t] = pows[t - 1] * s % MOD

        for t in range(K + 1):
            p = K - t
            term = binom[t] * pows[t] % MOD * cnt[p] % MOD
            if sign[p] == 1:
                ans += term
            else:
                ans -= term

        ans %= MOD

        for p in range(K + 1):
            cnt[p] += pows[p]
            if cnt[p] >= MOD:
                cnt[p] -= MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()

import sys

def construct(R, B):
    OFFSET = 500000000
    if R % 2 != 0:
        return None
    if R == 0:
        if B % 2 != 0:
            return None
        k = B // 2
        coords = []
        for x in range(k):
            coords.append((x, 0))
        for x in range(k - 1, -1, -1):
            coords.append((x, 1))
        pieces = []
        for u, v in coords:
            pieces.append(('B', u + v + OFFSET, u - v + OFFSET))
        return pieces
    if B == 0:
        k = R // 2
        pieces = []
        for c in range(1, k + 1):
            pieces.append(('R', 1 + OFFSET, c + OFFSET))
        for c in range(k, 0, -1):
            pieces.append(('R', 2 + OFFSET, c + OFFSET))
        return pieces

    if B % 2 == 1:
        m = R // 2
        red = [(0, 0)]
        for y in range(1, m + 1):
            red.append((0, y))
        if m >= 2:
            red.append((1, m))
        for y in range(m - 1, 1, -1):
            red.append((1, y))

        mB = (B - 1) // 2
        blue = [(1, 1)]
        for i in range(1, mB + 1):
            blue.append((1 + i, 1 - i))
        if mB >= 1:
            blue.append((mB, -mB))
        for j in range(mB - 1, 0, -1):
            blue.append((j, -j))
    else:
        m = R // 2
        k = m - 1
        red = [(0, 0), (1, 0)]
        for i in range(1, k + 1):
            red.append((1, -i))
        for i in range(k, 0, -1):
            red.append((2, -i))

        mB = B // 2
        blue = [(2, 0)]
        for i in range(1, mB):
            blue.append((2 + i, i))
        blue.append((mB, mB))
        for i in range(1, mB):
            blue.append((mB - i, mB - i))

    pieces = []
    for x, y in red:
        pieces.append(('R', x + OFFSET, y + OFFSET))
    for x, y in blue:
        pieces.append(('B', x + OFFSET, y + OFFSET))
    return pieces


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    T = int(data[0])
    idx = 1
    out = []
    for _ in range(T):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2
        pieces = construct(R, B)
        if pieces is None:
            out.append("No")
        else:
            out.append("Yes")
            for p, r, c in pieces:
                out.append(f"{p} {r} {c}")
    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def prefix(n: int) -> int:
            if n <= 0:
                return 0
            res = 0
            p = 1
            level = 1
            while p <= n:
                end = p * 4 - 1
                if end > n:
                    end = n
                res += level * (end - p + 1)
                p *= 4
                level += 1
            return res

        def max_level(n: int) -> int:
            c = 0
            while n > 0:
                n //= 4
                c += 1
            return c

        answer = 0
        for l, r in queries:
            total = prefix(r) - prefix(l - 1)
            mx = max_level(r)

            ops = (total + 1) // 2
            if mx > ops:
                ops = mx

            answer += ops

        return answer

