from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(x: int) -> int:
            if x <= 0:
                return 0

            digits = list(map(int, str(x)))
            n = len(digits)

            @lru_cache(maxsize=None)
            def dfs(pos: int, tight: bool, started: bool, sm: int, prod: int, has_zero: bool) -> int:
                if pos == n:
                    if not started or sm == 0:
                        return 0
                    return 1 if (has_zero or prod % sm == 0) else 0

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(limit + 1):
                    ntight = tight and (d == limit)

                    if not started and d == 0:
                        total += dfs(pos + 1, ntight, False, 0, 1, False)
                    else:
                        nsm = sm + d
                        if has_zero or d == 0:
                            total += dfs(pos + 1, ntight, True, nsm, 0, True)
                        else:
                            total += dfs(pos + 1, ntight, True, nsm, prod * d, False)

                return total

            return dfs(0, True, False, 0, 1, False)

        return count_up_to(r) - count_up_to(l - 1)

from typing import List

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        children = [{}]
        cnt = [0]
        depth = [0]
        paths = []

        for w in words:
            node = 0
            path = []
            for ch in w:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    cnt.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                cnt[node] += 1
                path.append(node)
            paths.append(path)

        max_depth = max(depth) if depth else 0
        total_qual = [0] * (max_depth + 1)

        for v in range(1, len(children)):
            if cnt[v] >= k:
                total_qual[depth[v]] += 1

        A = 0
        for d in range(max_depth, 0, -1):
            if total_qual[d] > 0:
                A = d
                break

        ans = []
        for path in paths:
            L = len(path)
            best_non = A if A > L else 0
            best_anc = 0

            for d, node in enumerate(path, 1):
                c = cnt[node]

                if c >= k + 1:
                    best_anc = d

                if total_qual[d] > (1 if c >= k else 0):
                    if d > best_non:
                        best_non = d

            ans.append(best_non if best_non > best_anc else best_anc)

        return ans

import sys
from math import isqrt

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])

    d = 1
    while d * d * d < N:
        if N % d == 0:
            q = N // d
            disc = 12 * q - 3 * d * d
            r = isqrt(disc)
            if r * r == disc:
                num = r - 3 * d
                if num > 0 and num % 6 == 0:
                    y = num // 6
                    x = y + d
