import sys
from collections import deque

sys.setrecursionlimit(10000)

class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        q = deque([s])
        self.level[s] = 0
        while q:
            v = q.popleft()
            for to, cap, rev in self.g[v]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[v] + 1
                    q.append(to)
        return self.level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.it[v], len(self.g[v])):
            self.it[v] = i
            to, cap, rev = self.g[v][i]
            if cap > 0 and self.level[v] + 1 == self.level[to]:
                d = self.dfs(to, t, min(f, cap))
                if d > 0:
                    self.g[v][i][1] -= d
                    self.g[to][rev][1] += d
                    return d
        return 0

    def max_flow(self, s, t, limit=10**18):
        flow = 0
        while flow < limit and self.bfs(s, t):
            self.it = [0] * self.n
            while flow < limit:
                f = self.dfs(s, t, limit - flow)
                if f == 0:
                    break
                flow += f
        return flow


def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])
    K = int(data[2])

    edges = []
    idx = 3
    for _ in range(M):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        idx += 2
        edges.append((u, v))

    ans = 0
    INF = 10**6

    for d in range(1, N):  # d = 1 .. N-1
        total_nodes = N * d + 2
        S = N * d
        T = N * d + 1
        dinic = Dinic(total_nodes)

        def node(v, i):
            # v: 0-indexed vertex, i: 1..d
            return v * d + (i - 1)

        # Monotonicity: y_{v,i+1} <= y_{v,i}
        for v in range(N):
            for i in range(1, d):
                dinic.add_edge(node(v, i + 1), node(v, i), INF)

        # Force l(1) = 0
        for i in range(1, d + 1):
            dinic.add_edge(node(0, i), T, INF)

        # Force l(N) = d
        for i in range(1, d + 1):
            dinic.add_edge(S, node(N - 1, i), INF)

        for u, v in edges:
            # Cost: max(0, l(v) - l(u))
            for i in range(1, d + 1):
                dinic.add_edge(node(v, i), node(u, i), 1)
            # Constraint: l(v) - l(u) <= 1
            for i in range(1, d):
                dinic.add_edge(node(v, i + 1), node(u, i), INF)

        flow = dinic.max_flow(S, T, K + 1)
        if flow <= K:
            ans = d
        else:
            break

    print(ans)


