class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_b = [[] for _ in range(n + 1)]

        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            by_b[b].append((a, idx))

        extra = [0] * m

        max1 = 0
        count1 = 0
        id1 = -1
        max2 = 0

        base = 0

        for r in range(1, n + 1):
            for a, idx in by_b[r]:
                if a > max1:
                    max2 = max1
                    max1 = a
                    count1 = 1
                    id1 = idx
                elif a == max1:
                    count1 += 1
                elif a > max2:
                    max2 = a

            base += r - max1

            if count1 == 1 and max1 > 0:
                extra[id1] += max1 - max2

        return base + max(extra)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        ans = ['?'] * L

        # Fill all positions forced by 'T'
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    if ans[pos] != '?' and ans[pos] != str2[j]:
                        return ""
                    ans[pos] = str2[j]

        # Process all 'F' constraints from left to right
        for i, ch in enumerate(str1):
            if ch == 'F':
                # Check if the window currently equals str2 when '?' is treated as 'a'
                equal = True
                for j in range(m):
                    c = ans[i + j]
                    if c == '?':
                        c = 'a'
                    if c != str2[j]:
                        equal = False
                        break

                if equal:
                    # Find the rightmost unassigned position in this window
                    for j in range(m - 1, -1, -1):
                        if ans[i + j] == '?':
                            ans[i + j] = 'b'
                            break
                    else:
                        return ""

        # Fill all remaining '?' with 'a' to get the lexicographically smallest string
        return ''.join('a' if c == '?' else c for c in ans)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        INF = 10**18

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(INF, fact[i - 1] * i)

        def count_ways(odd: int, even: int, req: int) -> int:
            m = odd + even
            need_odd = (m + 1) // 2 if req == 1 else m // 2
            if need_odd != odd:
                return 0
            return min(INF, fact[odd] * fact[even])

        unused = list(range(1, n + 1))
        ans = []

        for _ in range(n):
            prev = ans[-1] % 2 if ans else None
            chosen = -1

            for i, x in enumerate(unused):
                p = x % 2
                if prev is not None and p == prev:
                    continue

                odd = even = 0
                for j, y in enumerate(unused):
                    if j == i:
                        continue
                    if y % 2 == 1:
                        odd += 1
                    else:
                        even += 1

                req = 1 - p
                cnt = count_ways(odd, even, req)

                if k > cnt:
                    k -= cnt
                else:
                    chosen = i
                    ans.append(x)
                    unused.pop(i)
                    break

            if chosen == -1:
                return []

        return ans

