def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]
    U = [0] * N
    D = [0] * N
    total = 0
    M = 10**30

    idx = 2
    for i in range(N):
        u = data[idx]
        d = data[idx + 1]
        idx += 2
        U[i] = u
        D[i] = d
        total += u + d
        if u + d < M:
            M = u + d

    def feasible(H):
        L = H - D[0]
        if L < 0:
            L = 0
        R = U[0]
        if H < R:
            R = H
        if L > R:
            return False

        lo, hi = L, R

        for i in range(1, N):
            L = H - D[i]
            if L < 0:
                L = 0
            R = U[i]
            if H < R:
                R = H

            nlo = lo - X
            if nlo < L:
                nlo = L

            nhi = hi + X
            if nhi > R:
                nhi = R

            if nlo > nhi:
                return False

            lo, hi = nlo, nhi

        return True

    low = 0
    high = M + 1

    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    answer = total - N * low
    print(answer)


