import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    s = data[1].strip()

    # next_mask(x, d, t):
    # x = previous x state (0 or 1)
    # d = chosen indegree value for the current cycle vertex
    # t = 1 if s_i == '1' (spoke exists), else 0
    # returns bitmask of possible next x states:
    # bit0 = 1 means next x = 0 is possible
    # bit1 = 2 means next x = 1 is possible
    def next_mask(x, d, t):
        if t == 1:
            if x == 0:
                if d == 0: return 2  # next x = 1
                if d == 1: return 3  # next x = 0 or 1
                if d == 2: return 1  # next x = 0
                return 0
            else:
                if d == 1: return 2  # next x = 1
                if d == 2: return 3  # next x = 0 or 1
                if d == 3: return 1  # next x = 0
                return 0
        else:
            if x == 0:
                if d == 0: return 2  # next x = 1
                if d == 1: return 1  # next x = 0
                return 0
            else:
                if d == 1: return 2  # next x = 1
                if d == 2: return 1  # next x = 0
                return 0

    # trans_subset[t][mask][d] = union of next states from any state in mask
    trans_subset = [[[0] * 4 for _ in range(4)] for _ in range(2)]
    for t in range(2):
        for mask in range(4):
            for d in range(4):
                nm = 0
                if mask & 1:
                    nm |= next_mask(0, d, t)
                if mask & 2:
                    nm |= next_mask(1, d, t)
                trans_subset[t][mask][d] = nm

    # trans_list[t][state] = list of (next_state, multiplicity)
    # state = (A << 2) | B, where A, B are masks of possible states
    # starting from x=0 and x=1 respectively.
    trans_list = []
    for t in range(2):
        lst = [[] for _ in range(16)]
        for state in range(1, 16):
            A = state >> 2
            B = state & 3
            counts = {}
            for d in range(4):
                nA = trans_subset[t][A][d]
                nB = trans_subset[t][B][d]
                ns = (nA << 2) | nB
                if ns != 0:
                    counts[ns] = counts.get(ns, 0) + 1
            for ns, cnt in counts.items():
                lst[state].append((ns, cnt))
        trans_list.append(lst)

    # dp[state] = number of prefixes leading to this pair of subsets.
    # Initial: A = {0} = 1, B = {1} = 2 => state = (1<<2)|2 = 6
    dp = [0] * 16
    dp[6] = 1

    for ch in s:
        t = 1 if ch == '1' else 0
        trans = trans_list[t]
        ndp = [0] * 16
        for state in range(1, 16):
            val = dp[state]
            if val:
                for ns, cnt in trans[state]:
                    ndp[ns] += val * cnt
        for i in range(16):
            ndp[i] %= MOD
        dp = ndp

    ans = 0
    for state in range(1, 16):
        val = dp[state]
        if val:
            A = state >> 2
            B = state & 3
            # valid if there is a path from 0 to 0 (A has bit0)
            # or from 1 to 1 (B has bit1)
            if (A & 1) or (B & 2):
                ans = (ans + val) % MOD

    print(ans)

if __name__ == "__main__":
    solve()

