from bisect import bisect_left

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        S = side
        n = len(points)
        # Compute perimeter parameter and sort points clockwise
        pts = []
        for x, y in points:
            if y == 0:
                s = x
            elif x == S:
                s = S + y
            elif y == S:
                s = 2 * S + (S - x)
            else:
                s = 3 * S + (S - y)
            pts.append((s, x, y))
        pts.sort(key=lambda t: t[0])

        # Group points by side
        L = [-1] * 4
        R = [-1] * 4
        side = [0] * n
        coords = [[] for _ in range(4)]
        m = [0] * 4
        for i, (s, x, y) in enumerate(pts):
            t = s // S
            if t > 3:
                t = 3
            side[i] = t
            if L[t] == -1:
                L[t] = i
            R[t] = i
            if t == 0:
                coords[t].append(x)
            elif t == 1:
                coords[t].append(y)
            elif t == 2:
                coords[t].append(x)
            else:
                coords[t].append(y)
        for t in range(4):
            if L[t] != -1:
                m[t] = R[t] - L[t] + 1
            else:
                m[t] = 0

        inc = [True, True, False, False]
        neg_coords = [[] for _ in range(4)]
        for t in range(4):
            if not inc[t] and m[t] > 0:
                neg_coords[t] = [-c for c in coords[t]]

        def first_valid(t, o, p_lo, p_hi, D):
            if p_lo > p_hi:
                return None
            x, y = pts[o][1], pts[o][2]
            if t == 0:
                C = y
                c_p = x
            elif t == 1:
                C = S - x
                c_p = y
            elif t == 2:
                C = S - y
                c_p = x
            else:
                C = x
                c_p = y
            threshold = D - C
            if threshold <= 0:
                return p_lo
            A = c_p - threshold
            B = c_p + threshold
            if inc[t]:
                if coords[t][p_lo] <= A:
                    return p_lo
                idx = bisect_left(coords[t], B, p_lo, p_hi + 1)
                if idx <= p_hi:
                    return idx
                return None
            else:
                if coords[t][p_lo] >= B:
                    return p_lo
                idx = bisect_left(neg_coords[t], -A, p_lo, p_hi + 1)
                if idx <= p_hi:
                    return idx
                return None

        def find_next_orig(o, D):
            t = side[o]
            pos = o - L[t]
            mm = m[t]
            # suffix of current side
            if pos < mm - 1:
                res = first_valid(t, o, pos + 1, mm - 1, D)
                if res is not None:
                    return L[t] + res
            # next sides in clockwise order
            for d in range(1, 4):
                t2 = (t + d) % 4
                if m[t2] > 0:
                    res = first_valid(t2, o, 0, m[t2] - 1, D)
                    if res is not None:
                        return L[t2] + res
            # prefix of current side
            if pos > 0:
                res = first_valid(t, o, 0, pos - 1, D)
                if res is not None:
                    return L[t] + res
            return -1

        def check(D):
            if D == 0:
                return True
            next_o = [-1] * n
            for o in range(n):
                next_o[o] = find_next_orig(o, D)

            for i in range(n):
                cur = i
                ok = True
                for _ in range(k - 1):
                    o = cur % n
                    nxt = next_o[o]
                    if nxt == -1:
                        ok = False
                        break
                    delta = (nxt - o) % n
                    if delta == 0:
                        delta = n
                    cur += delta
                    if cur >= i + n:
                        ok = False
                        break
                if ok:
                    x1, y1 = pts[cur % n][1], pts[cur % n][2]
                    x2, y2 = pts[i][1], pts[i][2]
                    if abs(x1 - x2) + abs(y1 - y2) >= D:
                        return True
            return False

        low = 0
        high = S
        while low < high:
            mid = (low + high + 1) // 2
            if check(mid):
                low = mid
            else:
                high = mid - 1
        return low

