from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # direction order: DR, DL, UL, UR
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        ans = 0

        def compute_P(d: int):
            """P[i][j] = longest valid prefix ending at (i,j) moving in direction d,
               where the prefix starts with 1 and follows 1,2,0,2,0,...
            """
            dr, dc = dirs[d]
            P = [[0] * m for _ in range(n)]

            if dr > 0:
                rows = range(n)
            else:
                rows = range(n - 1, -1, -1)
            if dc > 0:
                cols = range(m)
            else:
                cols = range(m - 1, -1, -1)

            for i in rows:
                row = grid[i]
                Pi = P[i]
                for j in cols:
                    val = row[j]
                    if val == 1:
                        Pi[j] = 1
                    else:
                        pi = i - dr
                        pj = j - dc
                        if 0 <= pi < n and 0 <= pj < m:
                            pval = grid[pi][pj]
                            plen = P[pi][pj]
                            if val == 2:
                                if pval == 1:
                                    Pi[j] = 2
                                elif pval == 0 and plen:
                                    Pi[j] = plen + 1
                            elif val == 0:
                                if pval == 2 and plen:
                                    Pi[j] = plen + 1
            return P

        def compute_F(d: int):
            """F0[i][j] / F2[i][j] = longest alternating segment starting at (i,j)
               in direction d, starting with value 0 or 2 respectively.
            """
            dr, dc = dirs[d]
            F0 = [[0] * m for _ in range(n)]
            F2 = [[0] * m for _ in range(n)]

            if dr > 0:
                rows = range(n - 1, -1, -1)
            else:
                rows = range(n)
            if dc > 0:
                cols = range(m - 1, -1, -1)
            else:
                cols = range(m)

            for i in rows:
                row = grid[i]
                F0i = F0[i]
                F2i = F2[i]
                for j in cols:
                    val = row[j]
                    ni = i + dr
                    nj = j + dc
                    if val == 0:
                        if 0 <= ni < n and 0 <= nj < m:
                            F0i[j] = 1 + F2[ni][nj]
                        else:
                            F0i[j] = 1
                    elif val == 2:
                        if 0 <= ni < n and 0 <= nj < m:
                            F2i[j] = 1 + F0[ni][nj]
                        else:
                            F2i[j] = 1
            return F0, F2

        for d2 in range(4):
            d1 = (d2 - 1) % 4  # clockwise predecessor

            P = compute_P(d1)

            # no-turn (straight) segments
            for i in range(n):
                Pi = P[i]
                for j in range(m):
                    if Pi[j] > ans:
                        ans = Pi[j]

            F0, F2 = compute_F(d2)

            # one-turn segments
            for i in range(n):
                Pi = P[i]
                F0i = F0[i]
                F2i = F2[i]
                for j in range(m):
                    L = Pi[j]
                    if L >= 2:
                        # L odd -> turn cell value 0, L even -> turn cell value 2
                        F = F0i[j] if (L & 1) else F2i[j]
                        if F:
                            total = L + F - 1
                            if total > ans:
                                ans = total

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        qs = [part for part in parts if part]
        if not qs:
            return 0

        def get_occ(text: str, pat: str):
            n, m = len(text), len(pat)
            if m > n:
                return []

            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                lps[i] = j

            res = []
            j = 0
            for i in range(n):
                while j > 0 and text[i] != pat[j]:
                    j = lps[j - 1]
                if text[i] == pat[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = lps[j - 1]
            return res

        occ = [get_occ(s, q) for q in qs]
        for lst in occ:
            if not lst:
                return -1

        m = len(qs)
        if m == 1:
            return len(qs[0])

        if m == 2:
            len0, len1 = len(qs[0]), len(qs[1])
            best = 10**18
            j = 0
            occ1 = occ[1]
            for pos0 in occ[0]:
                need = pos0 + len0
                while j < len(occ1) and occ1[j] < need:
                    j += 1
                if j == len(occ1):
                    break
