from collections import defaultdict

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:]
    M = N - 1

    exp_dict = defaultdict(lambda: [0] * M)

    for i, a in enumerate(A):
        x = a
        d = 2
        while d * d <= x:
            if x % d == 0:
                cnt = 0
                while x % d == 0:
                    x //= d
                    cnt += 1
                exp_dict[d][i] += cnt
            d += 1
        if x > 1:
            exp_dict[x][i] += 1

    ans = 1

    for p, c_arr in exp_dict.items():
        S = sum(c_arr)

        powp = [1] * (S + 1)
        for e in range(1, S + 1):
            powp[e] = (powp[e - 1] * p) % MOD

        dp0 = [0] * (S + 1)
        dp1 = [0] * (S + 1)

        dp1[0] = 1
        for e in range(1, S + 1):
            dp0[e] = powp[e]

        for c in c_arr:
            if c == 0:
                if dp0[0]:
                    dp1[0] = (dp1[0] + dp0[0]) % MOD
                    dp0[0] = 0
                for e in range(1, S + 1):
                    if dp0[e]:
                        dp0[e] = (dp0[e] * powp[e]) % MOD
                    if dp1[e]:
                        dp1[e] = (dp1[e] * powp[e]) % MOD
            else:
                new0 = [0] * (S + 1)
                new1 = [0] * (S + 1)

                for e in range(S + 1):
                    v0 = dp0[e]
                    v1 = dp1[e]
                    if v0 == 0 and v1 == 0:
                        continue

                    ne = e + c
                    if ne <= S:
                        f = powp[ne]
                        if v0:
                            new0[ne] = (new0[ne] + v0 * f) % MOD
                        if v1:
                            new1[ne] = (new1[ne] + v1 * f) % MOD

                    ne = e - c
                    if ne >= 0:
                        f = powp[ne]
                        if ne == 0:
                            val = v0 + v1
                            if val >= MOD:
                                val -= MOD
                            new1[0] = (new1[0] + val * f) % MOD
                        else:
                            if v0:
                                new0[ne] = (new0[ne] + v0 * f) % MOD
                            if v1:
                                new1[ne] = (new1[ne] + v1 * f) % MOD

                dp0, dp1 = new0, new1

        F = sum(dp1) % MOD
        ans = (ans * F) % MOD

    print(ans)


