class Solution:
    def countSubstrings(self, s: str) -> int:
        # trans[d][c][r] = remainder after appending digit c to a number
        # whose current remainder modulo d is r.
        trans = [[None] * 10 for _ in range(10)]
        for d in range(1, 10):
            for c in range(10):
                trans[d][c] = [(r * 10 + c) % d for r in range(d)]

        counts = [None] * 10
        for d in range(1, 10):
            counts[d] = [0] * d

        ans = 0

        for ch in s:
            c = ord(ch) - ord('0')

            for d in range(1, 10):
                old = counts[d]
                new = [0] * d
                tr = trans[d][c]

                for r, val in enumerate(old):
                    if val:
                        new[tr[r]] += val

                new[c % d] += 1
                counts[d] = new

            if c != 0:
                ans += counts[c][0]

        return ans

