from math import gcd

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        M = 1 << m
        full = M - 1

        lcm = [1] * M
        for mask in range(1, M):
            L = 1
            for i in range(m):
                if mask & (1 << i):
                    t = target[i]
                    L = L // gcd(L, t) * t
            lcm[mask] = L

        submasks = [[] for _ in range(M)]
        for rem in range(M):
            s = rem
            while s:
                submasks[rem].append(s)
                s = (s - 1) & rem

        INF = 10**18
        dp = [INF] * M
        dp[0] = 0

        cache = {}
        for x in nums:
            cost = cache.get(x)
            if cost is None:
                cost = [0] * M
                for mask in range(1, M):
                    cost[mask] = (-x) % lcm[mask]
                cache[x] = cost

            ndp = dp[:]
            for covered in range(M):
                base = dp[covered]
                if base >= INF:
                    continue
                rem = full ^ covered
                for s in submasks[rem]:
                    cand = base + cost[s]
                    nm = covered | s
                    if cand < ndp[nm]:
                        ndp[nm] = cand
            dp = ndp

        return dp[full]

