    N = int(data[0])
    M = int(data[1])
    S = data[2]

    alphabet = [chr(ord('a') + i) for i in range(26)]
    states = 1 << N

    # transition[mask][char_index] = next mask
    transition = [[0] * 26 for _ in range(states)]

    for mask in range(states):
        L = [0] * (N + 1)
        for i in range(1, N + 1):
            L[i] = L[i - 1] + ((mask >> (i - 1)) & 1)

        for ci, c in enumerate(alphabet):
            newL = [0] * (N + 1)
            for i in range(1, N + 1):
                best = L[i]
                if newL[i - 1] > best:
                    best = newL[i - 1]
                if S[i - 1] == c:
                    val = L[i - 1] + 1
                    if val > best:
                        best = val
                newL[i] = best

            nmask = 0
            for i in range(1, N + 1):
                if newL[i] != newL[i - 1]:
                    nmask |= 1 << (i - 1)
            transition[mask][ci] = nmask

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask in range(states):
            cnt = dp[mask]
            if cnt == 0:
                continue
            tr = transition[mask]
            for ci in range(26):
                nmask = tr[ci]
                ndp[nmask] = (ndp[nmask] + cnt) % MOD
        dp = ndp

    popcount = [0] * states
    for i in range(1, states):
        popcount[i] = popcount[i >> 1] + (i & 1)

    ans = [0] * (N + 1)
    for mask in range(states):
        ans[popcount[mask]] = (ans[popcount[mask]] + dp[mask]) % MOD

    print(*ans)

