from typing import List

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        def count_pairs(a: int, b: int, K: int) -> int:
            if K < 0:
                return 0

            t_max = min(a - 1, K)
            if t_max < 0:
                return 0

            u = K + 1
            T = u - b
            total = 0

            full_end = min(t_max, T - 1)
            if full_end >= 0:
                total += b * (full_end + 1)

            lo = max(0, T)
            hi = t_max
            if lo <= hi:
                cnt = hi - lo + 1
                total += (2 * u - lo - hi) * cnt // 2

            return total

        def max_sum(arr: List[int]) -> int:
            n = len(arr)

            prev = [-1] * n
            st = []
            for i, x in enumerate(arr):
                while st and arr[st[-1]] < x:
                    st.pop()
                prev[i] = st[-1] if st else -1
                st.append(i)

            nxt = [n] * n
            st = []
            for i in range(n - 1, -1, -1):
                x = arr[i]
                while st and arr[st[-1]] <= x:
                    st.pop()
                nxt[i] = st[-1] if st else n
                st.append(i)

            K = k - 1
            ans = 0
            for i, x in enumerate(arr):
                a = i - prev[i]
                b = nxt[i] - i
                ans += x * count_pairs(a, b, K)

            return ans

        return max_sum(nums) - max_sum([-x for x in nums])

import sys

def mat_mul(A, B, mod):
    n = len(A)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ri = res[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(n):
                    Ri[j] += aik * Bk[j]
        for j in range(n):
            Ri[j] %= mod
    return res

def mat_pow(mat, exp, mod):
    n = len(mat)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1 % mod
    base = mat
    while exp > 0:
        if exp & 1:
            res = mat_mul(res, base, mod)
        exp >>= 1
        if exp:
            base = mat_mul(base, base, mod)
    return res

def solve():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    N = data[0]
    p = data[1]
    vals = data[2:]
    A = [vals[i*N:(i+1)*N] for i in range(N)]

    # Special case p = 2: every zero becomes 1, so B is uniquely determined.
    if p == 2:
        B = [[1 if x == 0 else x for x in row] for row in A]
        B2 = mat_pow(B, 2, 2)
        out = '\n'.join(' '.join(map(str, row)) for row in B2)
        sys.stdout.write(out)
        return

    K = 0
    F = []
    for row in A:
        new_row = []
        for x in row:
            if x == 0:
                K += 1
                new_row.append(0)
            else:
                new_row.append(x % p)
        F.append(new_row)

    Fp = mat_pow(F, p, p)

    T = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                if i == j:
                    a = i
                    # fixed edge entering the self-loop zero from c != a
                    for c in range(N):
                        if c != a:
                            val = A[c][a]
                            if val != 0:
                                T[c][a] = (T[c][a] + val) % p
                    # fixed edge leaving the self-loop zero to d != a
                    for d in range(N):
                        if d != a:
                            val = A[a][d]
                            if val != 0:
                                T[a][d] = (T[a][d] + val) % p
                else:
                    # Only for p = 3 can a non-self-loop zero edge contribute.
                    if p == 3:
                        val = A[j][i]
                        if val != 0:
                            T[i][j] = (T[i][j] + val) % p

    sign = -1 if K % 2 == 1 else 1
    ans = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            val = (Fp[i][j] + T[i][j]) % p
            if sign == -1:
                val = (-val) % p
            ans[i][j] = val

    out = '\n'.join(' '.join(map(str, row)) for row in ans)
    sys.stdout.write(out)

