    for v in A:
        indeg[v] += 1

    q = deque(i for i in range(N) if indeg[i] == 0)
    prod = [None] * N

    while q:
        u = q.popleft()
        arr = prod[u]

        # S[k] = sum_{t=1..k} F_u(t)
        S = [0] * (M + 1)
        if arr is None:
            for k in range(1, M + 1):
                S[k] = k
        else:
            run = 0
            for k in range(1, M + 1):
                run += arr[k]
                if run >= MOD:
                    run -= MOD
                S[k] = run

        p = A[u]
        parr = prod[p]
        if parr is None:
            prod[p] = S
        else:
            for k in range(1, M + 1):
                parr[k] = (parr[k] * S[k]) % MOD

        prod[u] = None
        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)

    visited = [False] * N
    ans = 1

    for i in range(N):
        if indeg[i] > 0 and not visited[i]:
            cyc = []
            cur = i
            while not visited[cur]:
                visited[cur] = True
                cyc.append(cur)
                cur = A[cur]

            G = [1] * (M + 1)
            for v in cyc:
                F = prod[v]
                if F is not None:
