                dp1[1] = 1
            else:
                dp0[1] = 1
                dp1[1] = 0

            for ch in s[1:]:
                ndp0 = [INF] * (L + 2)
                ndp1 = [INF] * (L + 2)

                cost0 = 0 if ch == '0' else 1
                cost1 = 1 - cost0

                best1 = min(dp1)
                if best1 < INF:
                    ndp0[1] = best1 + cost0

                for r in range(1, L):
                    if dp0[r] < INF:
                        ndp0[r + 1] = dp0[r] + cost0

                best0 = min(dp0)
                if best0 < INF:
                    ndp1[1] = best0 + cost1

                for r in range(1, L):
                    if dp1[r] < INF:
                        ndp1[r + 1] = dp1[r] + cost1

                dp0, dp1 = ndp0, ndp1

            return min(min(dp0), min(dp1)) <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    deg = [0] * (n + 1)
    edges = []

    pos = 1
    for _ in range(n - 1):
        u = data[pos]
        v = data[pos + 1]
        pos += 2
        edges.append((u, v))
        deg[u] += 1
        deg[v] += 1

    adj_deg = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj_deg[u].append(deg[v])
        adj_deg[v].append(deg[u])

    best = 0
    for i in range(1, n + 1):
        arr = adj_deg[i]
        if arr:
            arr.sort(reverse=True)
            for j, val in enumerate(arr, 1):
                if val >= 2:
                    prod = j * val
                    if prod > best:
                        best = prod
                else:
                    break

    print(n - 1 - best)

if __name__ == "__main__":
    main()

import sys
import heapq

def solve():
    input = sys.stdin.buffer.readline
    H, W, X = map(int, input().split())
    P, Q = map(int, input().split())
    p, q = P - 1, Q - 1

    S = [list(map(int, input().split())) for _ in range(H)]

    visited = [[False] * W for _ in range(H)]
    current = S[p][q]
    visited[p][q] = True

    heap = []
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for dr, dc in dirs:
        nr, nc = p + dr, q + dc
        if 0 <= nr < H and 0 <= nc < W:
            heapq.heappush(heap, (S[nr][nc], nr, nc))

    while heap:
        val, r, c = heapq.heappop(heap)

        if visited[r][c]:
            continue

        if val * X < current:
            current += val
            visited[r][c] = True

            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc]:
                    heapq.heappush(heap, (S[nr][nc], nr, nc))
        else:
            break

    print(current)

if __name__ == "__main__":
    solve()

import sys
from bisect import bisect_left

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    N = next(it)
    X = next(it)

    A = [0] * (N + 1)
    for i in range(1, N + 1):
        A[i] = next(it)

    B = [0] * (N + 1)
    for i in range(1, N + 1):
        B[i] = next(it)

    P = [0] * (N + 1)
    for i in range(1, N + 1):
        P[i] = next(it)

    Q = [0] * (N + 1)
    for i in range(1, N + 1):
        Q[i] = next(it)

    invP = [0] * (N + 1)
    for i in range(1, N + 1):
        invP[P[i]] = i

    invQ = [0] * (N + 1)
    for i in range(1, N + 1):
        invQ[Q[i]] = i

    def build(perm, inv, balls):
        dist = [-1] * (N + 1)
        nodes_by_dist = []

        cur = X
        d = 0
        while dist[cur] == -1:
            dist[cur] = d
            nodes_by_dist.append(cur)
            cur = inv[cur]
            d += 1

        D = 0
        for i in range(1, N + 1):
            if balls[i]:
                if dist[i] == -1:
                    return None
                if dist[i] > D:
                    D = dist[i]

        if D == 0:
            return []

        start = nodes_by_dist[D]
        seq = []
        cur = start
        while cur != X:
            seq.append(cur)
            cur = perm[cur]
        return seq

    SR = build(P, invP, A)
    if SR is None:
        print(-1)
        return

    SB = build(Q, invQ, B)
    if SB is None:
        print(-1)
        return

    pos = [-1] * (N + 1)
    for idx, v in enumerate(SR):
        pos[v] = idx

    tails = []
    for v in SB:
        p = pos[v]
        if p != -1:
            j = bisect_left(tails, p)
            if j == len(tails):
                tails.append(p)
            else:
                tails[j] = p

    lcs = len(tails)
    ans = len(SR) + len(SB) - lcs
    print(ans)

if __name__ == "__main__":
    solve()

import sys

def solve() -> None:
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N = data[0]
    A = [0] + data[1:1 + N] + [0]

    left = [-1] * (N + 1)
    right = [-1] * (N + 1)

    stack = []
    for i in range(1, N + 1):
        ai = A[i]
        last = -1
        while stack and A[stack[-1]] < ai:
            last = stack.pop()
        if stack:
            right[stack[-1]] = i
        if last != -1:
            left[i] = last
        stack.append(i)

    root = stack[0]

    S = A[:]
    order = []
    st = [root]
    while st:
        u = st.pop()
        order.append(u)
        l = left[u]
        r = right[u]
        if l != -1:
            st.append(l)
        if r != -1:
            st.append(r)

    for u in reversed(order):
        l = left[u]
        r = right[u]
        if l != -1:
            S[u] += S[l]
        if r != -1:
            S[u] += S[r]

    dp = [0] * (N + 1)
    dp[root] = root
    for u in order:
        l = left[u]
        r = right[u]
        if l != -1:
            if S[l] > A[u]:
                dp[l] = dp[u]
            else:
                dp[l] = l
        if r != -1:
            if S[r] > A[u]:
                dp[r] = dp[u]
            else:
                dp[r] = r

    ans = []
    for u in range(1, N + 1):
        l = left[u]
        r = right[u]
        if l == -1 and r == -1:
            can = True
        else:
            can = (l != -1 and A[u - 1] < A[u]) or (r != -1 and A[u + 1] < A[u])
        if can:
            ans.append(str(S[dp[u]]))
        else:
            ans.append(str(A[u]))

    sys.stdout.write(' '.join(ans))

if __name__ == '__main__':
    solve()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold

        small = []
        idx_of = [-1] * (T + 1)
        isolated = 0

        for v in nums:
            if v > T:
                isolated += 1
            else:
                idx_of[v] = len(small)
                small.append(v)

        m = len(small)
        parent = list(range(m))
        size = [1] * m

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        last = [-1] * (T + 1)

        for i, x in enumerate(small):
            for multiple in range(x, T + 1, x):
                prev = last[multiple]
                if prev != -1:
                    union(i, idx_of[prev])
                last[multiple] = x

        components = 0
        for i in range(m):
            if find(i) == i:
                components += 1

        return isolated + components
